#include <bitset>

void demonstrate_reference() {
    std::bitset<10> flags(0b1010);

    // 1. Assignment using proxy
    flags[0] = true; // Sets bit 0

    // 2. Assignment from another bit (via proxy)
    flags[1] = flags[3]; // flags[1] is now false

    // 3. Toggling using proxy method
    flags[2].flip(); // Toggles bit 2 (1 -> 0)

    // 4. Reading using operator bool()
    if (flags[0]) { 
        flags[4] = ~flags[2]; // Assigns complement (1)
    }
}
